interface BrickData {
  globalIndex: number;
  gridX: number;
  gridY: number;
}

const Brick: React.FC<{
  data: BrickData;
  cellSize: number;
  targetX: number;
  targetY: number;
  color: string;
  staggerFrames: number;
  fallDurationFrames: number;
}> = ({
  data,
  cellSize,
  targetX,
  targetY,
  color,
  staggerFrames,
  fallDurationFrames,
}) => {
  const frame = useCurrentFrame();
  const { height } = useVideoConfig();

  const delay = data.globalIndex * staggerFrames;
  const t = frame - delay;
  const isVisible = t >= 0;

  // The brick falls from off-screen top.
  const yFall = interpolate(t, [0, fallDurationFrames], [-height * 0.8, targetY], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.in(Easing.poly(3)),
  });

  // The brick lands slightly to the left, then slides firmly into position to 'lock'
  const slideDuration = 6;
  const slideOffset = cellSize * 0.6;
  
  const xPos = interpolate(
    t,
    [fallDurationFrames, fallDurationFrames + slideDuration],
    [targetX - slideOffset, targetX],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.back(1.5)),
    }
  );

  // A tiny vertical bump to simulate the friction/click of snapping into place
  const yBump = interpolate(
    t,
    [fallDurationFrames, fallDurationFrames + slideDuration / 2, fallDurationFrames + slideDuration],
    [0, -cellSize * 0.1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.quad),
    }
  );

  const finalY = yFall + yBump;

  // Dynamic shadow that tightens as it gets closer to the surface
  const shadowOffset = interpolate(t, [0, fallDurationFrames], [20, 2], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const shadowBlur = interpolate(t, [0, fallDurationFrames], [30, 4], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const shadowOpacity = interpolate(t, [0, fallDurationFrames], [0.05, 0.3], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  if (!isVisible) return null;

  return (
    <div
      style={{
        position: "absolute",
        left: xPos,
        top: finalY,
        width: cellSize,
        height: cellSize,
        backgroundColor: color,
        borderRadius: "2px",
        boxShadow: `inset -2px -2px 6px rgba(0,0,0,0.3), inset 2px 2px 6px rgba(255,255,255,0.4), ${shadowOffset}px ${shadowOffset}px ${shadowBlur}px rgba(0,0,0,${shadowOpacity})`,
        transition: "none",
        zIndex: 1000 - data.globalIndex, // Ensure proper layering if overlapping slightly during fall
      }}
    >
      {/* Central Stud */}
      <div
        style={{
          position: "absolute",
          top: "18%",
          left: "18%",
          width: "64%",
          height: "64%",
          borderRadius: "50%",
          backgroundColor: color,
          boxShadow:
            "inset -1px -1px 3px rgba(0,0,0,0.3), inset 1px 1px 3px rgba(255,255,255,0.6), 1.5px 1.5px 3px rgba(0,0,0,0.4)",
          transition: "none",
        }}
      />
    </div>
  );
};

const columnsPerLetter = 5;
const gapBetweenLetters = 2;

const MalloyLego: React.FC<MalloyLegoProps> = ({
  text = "MALLOY",
  backgroundColor = "#f4f4f5",
  transparentBackground = false,
  durationInSeconds = 8,
  brickColors = ["#E3000B", "#0055A6", "#F2C400", "#00852B", "#FFFFFF"],
  staggerFrames = 1.8,
  fallDurationFrames = 12,
}) => {
  useFontLoader(["Inter"]);

  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Convert text string into array of 5x7 grids
  const letterGrids = useMemo(() => {
    return text.toUpperCase().split("").map((char) => ALPHABET_GRIDS[char] || ALPHABET_GRIDS[" "]);
  }, [text]);

  // Calculate layout sizes
  const totalLetters = letterGrids.length;
  const totalGridColumns = totalLetters > 0 
    ? totalLetters * columnsPerLetter + (totalLetters - 1) * gapBetweenLetters
    : 0;
  const totalGridRows = 7;

  // Make it responsive but fit comfortably within 16:9
  const maxCellWidth = totalGridColumns > 0 ? (width * 0.7) / totalGridColumns : 0;
  const maxCellHeight = (height * 0.5) / totalGridRows;
  const cellSize = Math.floor(Math.min(maxCellWidth, maxCellHeight));

  const totalWidth = totalGridColumns * cellSize;
  const totalHeight = totalGridRows * cellSize;

  const startX = (width - totalWidth) / 2;
  const startY = (height - totalHeight) / 2 + cellSize; // Shift slightly down for better optical centering

  // Parse grids into ordered brick sequence
  const bricks = useMemo(() => {
    const parsedBricks: BrickData[] = [];
    let globalIdx = 0;

    letterGrids.forEach((grid, letterIdx) => {
      const letterOffsetX = letterIdx * (columnsPerLetter + gapBetweenLetters);
      const letterBricks: { localX: number; localY: number }[] = [];

      grid.forEach((rowStr, rowIndex) => {
        for (let colIndex = 0; colIndex < rowStr.length; colIndex++) {
          if (rowStr[colIndex] === "1") {
            letterBricks.push({
              localX: colIndex,
              localY: rowIndex,
            });
          }
        }
      });

      // Sort: bottom-up (y descending), then left-right (x ascending)
      letterBricks.sort((a, b) => b.localY - a.localY || a.localX - b.localX);

      letterBricks.forEach((b) => {
        parsedBricks.push({
          globalIndex: globalIdx++,
          gridX: letterOffsetX + b.localX,
          gridY: b.localY,
        });
      });
    });

    return parsedBricks;
  }, [letterGrids]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        overflow: "hidden",
      }}
    >
      {bricks.map((brick) => {
        // Pseudo-random but deterministic color assignment based on index
        const colorIndex = (brick.globalIndex * 7 + 13) % brickColors.length;
        const color = brickColors[colorIndex];

        const targetX = startX + brick.gridX * cellSize;
        const targetY = startY + brick.gridY * cellSize;

        return (
          <Brick
            key={brick.globalIndex}
            data={brick}
            cellSize={cellSize}
            targetX={targetX}
            targetY={targetY}
            color={color}
            staggerFrames={staggerFrames}
            fallDurationFrames={fallDurationFrames}
          />
        );
      })}
    </AbsoluteFill>
  );
};

export default MalloyLego;